import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import "./p.css"; // Unique CSS styles

const Profile = () => {
    const navigate = useNavigate();
    const [user, setUser] = useState(null);

    useEffect(() => {
        const storedUser = JSON.parse(localStorage.getItem("user"));
        if (!storedUser) {
            navigate("/signin");
            return;
        }

        // Fetch user data by ID
        fetch(`http://localhost:8080/api/auth/user/${storedUser.id}`)
            .then((res) => res.json())
            .then((data) => setUser(data))
            .catch((err) => {
                console.error("Failed to load user", err);
                navigate("/signin");
            });
    }, [navigate]);

    if (!user) return <p className="p-l">Loading...</p>;

    return (
        <div className="p-box">
            <h1 className="p-h">👤 User Profile</h1>
            <div className="p-grid">
                <div className="p-row"><span className="p-key">Name:</span> {user.firstname} {user.lastname}</div>
                <div className="p-row"><span className="p-key">Email:</span> {user.email}</div>
                <div className="p-row"><span className="p-key">ID:</span> {user.id}</div>
            </div>
        </div>
    );
};

export default Profile;
